<script lang="ts">
 import SourceSummary from './SourceSummary.svelte';
 import {onMount} from 'svelte';import {Button} from '$lib/components/ui/button';import {ArrowLeft,Download,ArrowUpRight,Play} from '@lucide/svelte';import {request} from '../api';
 let {jobId}:{jobId:string}=$props();let output=$state<any>(null),error=$state(''),busy=$state(false),preview=$state(''),download=$state(''),projectId=$state('');
 async function load(){error='';try{const [asset,job]=await Promise.all([request(`/jobs/${encodeURIComponent(jobId)}/output`),request(`/jobs/${encodeURIComponent(jobId)}`)]);output=asset;projectId=job.project_id||'';}catch(e){error=(e as Error).message;}}
 onMount(()=>{void load();});async function grant(action:'preview'|'download'){busy=true;error='';try{const data=await request(`/media-assets/${output.asset_id}/${action}`);if(action==='preview')preview=data.url;else download=data.url;}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<a class="back-link" href="/studio/videos"><ArrowLeft class="size-4"/>Your videos</a><div class="page-heading"><h1>Your finished video</h1><p>Review your output, publish it on VideoFlow, or keep a copy.</p></div>
{#if error}<div class="cloud-alert" role="alert">{error}<Button variant="ghost" onclick={load}>Try again</Button></div>{/if}
{#if output}<SourceSummary asset={output} label="Output details"/><div class="output-preview">{#if preview}<video src={preview} controls playsinline preload="metadata"><track kind="captions"/></video>{:else}<Play class="size-10"/><p>Only you can preview this output.</p><Button variant="outline" disabled={busy} onclick={()=>grant('preview')}>Preview video</Button>{/if}</div><div class="output-actions"><Button href={output.publication_id?`/studio/publish?video=${output.publication_id}`:`/studio/publish?asset=${output.asset_id}`}>{output.publication_id?'Edit publication':'Publish on VideoFlow'}<ArrowUpRight class="size-4"/></Button>{#if projectId}<Button variant="outline" href={`/studio/editor?project=${encodeURIComponent(projectId)}`}>Open editor</Button>{/if}<Button variant="outline" disabled={busy} onclick={()=>grant('download')}><Download class="size-4"/>Prepare download</Button>{#if download}<a class="download-link" href={download}>Download {output.content_type==='video/webm'?'WebM':'MP4'}</a>{/if}</div><p class="field-help">Downloading keeps your video private. Publishing lets you choose who can watch it. Download links expire after a few minutes.</p>{:else if !error}<p role="status">Loading your output…</p>{/if}
<style>.back-link{display:flex;gap:8px;align-items:center;color:var(--muted-foreground);font-size:12px;margin-bottom:24px}.output-preview{aspect-ratio:16/9;background:var(--muted);display:flex;flex-direction:column;gap:16px;align-items:center;justify-content:center;border-radius:12px;overflow:hidden;max-height:65vh}.output-preview video{width:100%;height:100%;object-fit:contain}.output-preview p{font-size:13px;color:var(--muted-foreground)}.output-actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:24px 0 15px}.download-link{font-size:13px;text-decoration:underline;text-underline-offset:4px}</style>
